CREATE OR REPLACE FUNCTION public.marketplace_review_listing(p_listing_id uuid, p_decision text, p_internal_notes text DEFAULT NULL::text, p_seller_message text DEFAULT NULL::text)
 RETURNS TABLE(listing_id uuid, verification_status text, listing_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_listing public.user_card_flags%rowtype;
  v_reviewer_id uuid := (select auth.uid());
  v_decision text := lower(trim(coalesce(p_decision, '')));
  v_internal_notes text := nullif(trim(coalesce(p_internal_notes, '')), '');
  v_seller_message text := nullif(trim(coalesce(p_seller_message, '')), '');
  v_result_verification_status text;
  v_result_listing_status text;
begin
  if v_reviewer_id is null or not exists (
    select 1
    from public.profiles reviewer
    where reviewer.id = v_reviewer_id
      and reviewer.role in ('admin', 'moderator')
  ) then
    raise exception 'Marketplace reviewer access required.'
      using errcode = '42501';
  end if;

  if v_decision not in ('approve', 'reject', 'request_more_evidence') then
    raise exception 'Unsupported marketplace review decision.'
      using errcode = '22023';
  end if;

  if char_length(coalesce(v_internal_notes, '')) > 2000
    or char_length(coalesce(v_seller_message, '')) > 500 then
    raise exception 'Marketplace review notes are too long.'
      using errcode = '22023';
  end if;

  if v_decision in ('reject', 'request_more_evidence')
    and (v_internal_notes is null or v_seller_message is null) then
    raise exception 'Internal notes and a seller message are required for this decision.'
      using errcode = '22023';
  end if;

  select listing.* into v_listing
  from public.user_card_flags listing
  where listing.id = p_listing_id
    and listing.flag_type = 'trade'
  for update;

  if not found then
    raise exception 'Marketplace listing not found.'
      using errcode = 'P0002';
  end if;

  if coalesce(v_listing.listing_status, 'active') <> 'active'
    or (v_listing.verification_status <> 'pending' and not v_listing.admin_review_required) then
    raise exception 'Marketplace listing is no longer awaiting review.'
      using errcode = '55000';
  end if;

  if v_decision = 'approve' then
    v_result_verification_status := 'verified';
    v_result_listing_status := 'active';
  elsif v_decision = 'reject' then
    v_result_verification_status := 'rejected';
    v_result_listing_status := 'archived';
  else
    v_result_verification_status := 'pending';
    v_result_listing_status := 'active';
  end if;

  update public.user_card_flags listing
  set
    verification_status = v_result_verification_status,
    verification_completed_at = case
      when v_result_verification_status = 'verified' then timezone('utc', now())
      else null
    end,
    admin_review_required = v_result_verification_status = 'pending',
    admin_review_reason = case
      when v_decision = 'approve' then null
      when v_decision = 'reject' then v_seller_message
      else concat('Additional evidence requested: ', v_seller_message)
    end,
    listing_status = v_result_listing_status,
    updated_at = timezone('utc', now())
  where listing.id = v_listing.id;

  insert into public.marketplace_listing_review_events (
    listing_id,
    seller_user_id,
    reviewer_user_id,
    decision,
    previous_verification_status,
    resulting_verification_status,
    previous_listing_status,
    resulting_listing_status,
    internal_notes,
    seller_message,
    listing_snapshot
  ) values (
    v_listing.id,
    v_listing.user_id,
    v_reviewer_id,
    v_decision,
    v_listing.verification_status,
    v_result_verification_status,
    v_listing.listing_status,
    v_result_listing_status,
    v_internal_notes,
    v_seller_message,
    jsonb_build_object(
      'cardId', v_listing.card_id,
      'setId', v_listing.set_id,
      'productType', v_listing.product_type,
      'productName', v_listing.product_name,
      'askingPrice', v_listing.asking_price,
      'marketEstimate', v_listing.market_estimate,
      'reviewReason', v_listing.admin_review_reason
    )
  );

  return query select
    v_listing.id,
    v_result_verification_status,
    v_result_listing_status;
end;
$function$

CREATE OR REPLACE FUNCTION public.stackr_protect_profile_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
begin
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if auth.uid() is null or new.id is distinct from auth.uid() then
      raise exception 'profile_authority_violation: id must match verified identity'
        using errcode = '42501';
    end if;

    if coalesce(new.role, 'user') <> 'user'
      or new.email is not null
      or new.stripe_account_id is not null
    then
      raise exception 'profile_authority_violation: protected fields are server-controlled'
        using errcode = '42501';
    end if;
  elsif new.id is distinct from old.id
    or new.email is distinct from old.email
    or new.role is distinct from old.role
    or new.stripe_account_id is distinct from old.stripe_account_id
    or new.created_at is distinct from old.created_at
  then
    raise exception 'profile_authority_violation: protected fields are immutable to clients'
      using errcode = '42501';
  end if;

  return new;
end;
$function$
